        ("Completed", "Hoàn thành"), ("Cancelled", "Đã hủy")
    };

    private List<Order> _orders = new();
    private readonly Dictionary<int, string> _pending = new();
    private string? _alert;

    protected override async Task OnParametersSetAsync() => await LoadAsync();

    private async Task LoadAsync()
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        var query = db.Orders
            .Include(o => o.Customer)
            .Include(o => o.OrderDetails).ThenInclude(od => od.Product)
            .AsQueryable();
        if (!string.IsNullOrWhiteSpace(StatusFilter))
            query = query.Where(o => o.OrderStatus == StatusFilter);
        _orders = await query.OrderByDescending(o => o.OrderDate).ToListAsync();
        _pending.Clear();
    }

    private void SetPending(int orderId, string? status)
    {
        if (!string.IsNullOrEmpty(status)) _pending[orderId] = status;
    }

    private async Task SaveStatus(int orderId)
    {
        if (!_pending.TryGetValue(orderId, out var newStatus)) return;

        await using var db = await DbFactory.CreateDbContextAsync();
        var order = await db.Orders.FindAsync(orderId);
        if (order == null) return;
        order.OrderStatus = newStatus;
        await db.SaveChangesAsync();
        _alert = $"Cập nhật trạng thái đơn hàng #{orderId} thành: {newStatus}";
        await LoadAsync();
    }

